// L'app envoie chaque champ séparément ET un blob JSON 'metadata'
// On lit les champs directs d'abord, sinon on parse le JSON
const item = $input.first().json;

function get(field) {
  // Champ direct (nouveau comportement)
  if (item[field] && item[field] !== '') return item[field];
  // Sous body (certaines versions n8n)
  if (item.body && item.body[field]) return item.body[field];
  return '';
}

// Fallback : parser le blob JSON metadata si les champs directs sont vides
let meta = {};
try {
  const raw = get('metadata') || item.body?.metadata || '{}';
  // Si raw ressemble à du JSON objet, le parser
  if (raw.startsWith('{')) meta = JSON.parse(raw);
} catch(e) {}

const jobNum     = get('job_number')   || meta.job_number   || 'N/A';
const client     = get('client_name')  || meta.client_name  || 'N/A';
const adresse    = get('job_address')  || meta.job_address  || 'N/A';
const foreman    = get('foreman_name') || meta.foreman_name || 'N/A';
const dateLocale = get('date_locale')  || meta.date_locale  || new Date().toLocaleDateString('fr-CA');
const heure      = get('heure_locale') || meta.heure_locale || new Date().toLocaleTimeString('fr-CA', {hour:'2-digit',minute:'2-digit'});

const sujet = `Compte rendu — Chantier ${jobNum} — ${dateLocale}`;

const corps = `Bonjour,

Veuillez trouver ci-joint le compte rendu de la journée pour :

• Chantier :       ${jobNum}
• Client :         ${client}
• Adresse :        ${adresse}
• Chef d'équipe :  ${foreman}
• Date :           ${dateLocale} à ${heure}

Documents joints :
  - Bon de travail
  - Fiche de chantier
  - Checklist qualité
  - Suivi des matériaux
  - Rapport de satisfaction

Bonne journée,
Système InnovaSpray Québec`;

return [{ json: { sujet, corps, jobNum, client, adresse, foreman, dateLocale, heure } }];
